import { useState } from 'react';
import { LogIn, LogOut } from 'lucide-react';

import { Button } from '@/components/ui/button';
import { useAuthSession } from '@/hooks/use-auth-session';
import { signOut } from '@/lib/auth-actions';

/**
 * Session indicator for the workspace sidebar. It uses a plain anchor so the
 * access page works even before the route tree is regenerated by the build.
 */
export function AuthStatus() {
  const session = useAuthSession();
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');

  async function handleSignOut() {
    if (busy) return;
    setBusy(true);
    setError('');
    const result = await signOut();
    if (!result.ok) setError(result.message);
    setBusy(false);
  }

  if (session.status === 'loading') {
    return <div className="text-xs text-muted-foreground">Comprobando sesión…</div>;
  }

  if (session.status === 'authenticated') {
    return (
      <div className="space-y-2">
        <div className="flex items-center justify-between gap-2 text-xs">
          <span className="truncate" title={session.email ?? 'Cuenta TAMV'}>
            {session.email ?? 'Cuenta TAMV'}
          </span>
          <Button
            variant="ghost"
            size="sm"
            className="h-7 shrink-0 px-2"
            onClick={handleSignOut}
            disabled={busy}
            aria-label="Cerrar sesión"
          >
            <LogOut size={14} />
            {busy ? 'Saliendo…' : 'Salir'}
          </Button>
        </div>
        {error && (
          <p role="alert" className="text-xs text-destructive">
            {error}
          </p>
        )}
      </div>
    );
  }

  return (
    <a
      href="/auth"
      className="inline-flex items-center gap-2 rounded-md border border-primary/30 bg-primary/5 px-3 py-2 text-xs font-semibold text-primary hover:bg-primary/10"
    >
      <LogIn size={14} />
      Iniciar sesión
    </a>
  );
}
